import { afterEach, describe, expect, it, vi } from "vitest";

import {
  MAX_STATIC_FILE_SIZE,
  handleStaticFileRequest,
  type StaticFileMetadata,
  type StaticFileObject,
  type StaticFileStorage,
} from "./static";
import type {
  RandomBytes,
  ShortlinkRecord,
  ShortlinkStorage,
} from "./shortlinks";

class MemoryStaticFileStorage implements StaticFileStorage {
  readonly objects = new Map<
    string,
    {
      body: Uint8Array;
      expiresAt?: Date;
      metadata: StaticFileMetadata;
      uploaded: Date;
    }
  >();

  async get(key: string): Promise<StaticFileObject | null> {
    const object = this.objects.get(key);
    if (!object) return null;

    return this.toObject(key, object, true);
  }

  async head(key: string): Promise<StaticFileObject | null> {
    const object = this.objects.get(key);
    if (!object) return null;

    return this.toObject(key, object, false);
  }

  async put(
    key: string,
    value: ReadableStream<Uint8Array>,
    metadata: StaticFileMetadata,
    expiresAt?: Date,
  ): Promise<StaticFileObject> {
    const body = new Uint8Array(await new Response(value).arrayBuffer());
    const object = {
      body,
      metadata,
      uploaded: new Date("2026-07-13T00:00:00Z"),
      ...(expiresAt ? { expiresAt } : {}),
    };
    this.objects.set(key, object);
    return this.toObject(key, object, false);
  }

  async delete(key: string): Promise<void> {
    this.objects.delete(key);
  }

  private toObject(
    key: string,
    object: {
      body: Uint8Array;
      expiresAt?: Date;
      metadata: StaticFileMetadata;
      uploaded: Date;
    },
    includeBody: boolean,
  ): StaticFileObject {
    return {
      body: includeBody
        ? new ReadableStream<Uint8Array>({
            start(controller) {
              controller.enqueue(object.body);
              controller.close();
            },
          })
        : null,
      httpEtag: `"${key}-${object.body.byteLength}"`,
      metadata: object.metadata,
      size: object.body.byteLength,
      uploaded: object.uploaded,
      ...(object.expiresAt ? { expiresAt: object.expiresAt } : {}),
    };
  }
}

class MemoryShortlinkStorage implements ShortlinkStorage {
  readonly records = new Map<string, ShortlinkRecord>();

  async delete(code: string): Promise<void> {
    this.records.delete(code);
  }

  async get(code: string): Promise<ShortlinkRecord | null> {
    return this.records.get(code) ?? null;
  }

  async putIfAbsent(code: string, record: ShortlinkRecord): Promise<boolean> {
    if (this.records.has(code)) return false;
    this.records.set(code, record);
    return true;
  }
}

